public void doIt(final View view) {
    final Application app = getApplication();
    app.setEnabled(true);
    // If there is another view with we set the multiple open
    // id of our view to max(multiple open id) + 1.
    int multipleOpenId = 1;
    for (View aView : app.views()) {
        if (((aView != view) && ((aView.getFile()) != null)) && (aView.getFile().equals(file))) {
            multipleOpenId = Math.max(multipleOpenId, ((aView.getMultipleOpenId()) + 1));
        }
    }
    view.setMultipleOpenId(multipleOpenId);
    // Open the file
    view.execute(new Worker() {
        public Object construct() {
            try {
                view.read(file);
                return null;
            } catch (Throwable e) {
                return e;
            }
        }

        public void finished(Object value) {
            fileOpened(view, file, value);
        }
    });
}

protected void fileOpened(final View view, File file, Object value) {
    final Application app = getApplication();
    if (value == null) {
        view.setFile(file);
        view.setEnabled(true);
        Frame w = ((Frame) (SwingUtilities.getWindowAncestor(view.getComponent())));
        if (w != null) {
            w.setExtendedState(((w.getExtendedState()) & (~(Frame.ICONIFIED))));
            w.toFront();
        }
        view.getComponent().requestFocus();
        if (app != null) {
            app.setEnabled(true);
        }
    } else {
        if (value instanceof Throwable) {
