        draw(g, toDraw);
    }
}

public void draw(Graphics2D g, Collection<Figure> children) {
    Rectangle2D clipBounds = g.getClipBounds();
    if (clipBounds != null) {
        for (Figure f : children) {
            if ((f.isVisible()) && (f.getDrawingArea().intersects(clipBounds))) {
                f.draw(g);
            }
        }
    } else {
        for (Figure f : children) {
            if (f.isVisible()) {
                f.draw(g);
            }
        }
    }
}

