        if (DefaultDrawingViewTransferHandler.DEBUG) {
            ex.printStackTrace();
        }
    } catch (UnsupportedFlavorException ex) {
        if (DefaultDrawingViewTransferHandler.DEBUG) {
            ex.printStackTrace();
        }
    }
    return image == null ? null : new ImageIcon(image);
}

