        } else
            if ((((((((evt.getClickCount()) == 1) && ((evt.getModifiersEx()) == 0)) && ((lastClickEvent) != null)) && ((lastClickEvent.getClickCount()) == 1)) && ((lastClickEvent.getModifiersEx()) == 0)) && ((lastClickEvent.getX()) == (evt.getX()))) && ((lastClickEvent.getY()) == (evt.getY()))) {
