public boolean importData(TransferHandler.TransferSupport support) {
    if (DnDDrawingViewTransferHandler.DEBUG) {
        System.out.println(((this) + ".importData(support)"));
    }
    HashSet<Figure> transferFigures = new HashSet<Figure>();
    boolean success = ((support.getComponent()) instanceof JComponent) ? importData(((JComponent) (support.getComponent())), support.getTransferable(), transferFigures) : false;
