        // XXX - instead of centering, we have to translate by the drag image offset here
        t.translate(((drawingArea.width) / (-2.0)), ((drawingArea.height) / (-2.0)));
        for (Figure fig : transferFigures) {
            fig.willChange();
            fig.transform(t);
            fig.changed();
        }
    }
