public Point2D.Double chop(Point2D.Double from) {
    Rectangle2D.Double r = getBounds();
    if ((AttributeKeys.STROKE_COLOR.get(this)) != null) {
        double grow;
        switch (AttributeKeys.STROKE_PLACEMENT.get(this)) {
