                break;
            case OUTSIDE :
                grow = AttributeKeys.getStrokeTotalWidth(this);
                break;
            case INSIDE :
                grow = 0.0;
                break;
        }
        Geom.grow(r, grow, grow);
    }
    return Geom.angleToPoint(r, Geom.pointToAngle(r, from));
