public Point2D.Double locate(Figure owner) {
    Rectangle2D.Double r;
    if ((owner instanceof DecoratedFigure) && ((((DecoratedFigure) (owner)).getDecorator()) != null)) {
        r = ((DecoratedFigure) (owner)).getDecorator().getBounds();
    } else {
        r = owner.getBounds();
