    if (isQuadratic) {
        double side = Math.max(r.width, r.height);
        r.x -= (side - (r.width)) / 2;
        r.y -= (side - (r.height)) / 2;
        r.width = r.height = side;
    }
    return new Point2D.Double(((r.x) + ((r.width) * (relativeX))), ((r.y) + ((r.height) * (relativeY))));
}

