        } 
        Point2D.Double sp = start.findStart(figure);
        Point2D.Double ep = end.findEnd(figure);
        Rectangle2D.Double sb = start.getBounds();
        Rectangle2D.Double eb = end.getBounds();
        int soutcode = sb.outcode(sp);
