        if (dx > 0) {
            if (dy == 0) {
                return TranslationDirection.EAST;
            } else
                if (dy > 0) {
                    return TranslationDirection.SOUTH_EAST;
                } else {
                    return TranslationDirection.NORTH_EAST;
                }

        } else {
