/**
 * Adds the curve to the bezier path.
 *
 * @param bezCurve
 * 		
 * @param bezierPath
 * 		
 */
private static void addCurveTo(Point2D.Double[] bezCurve, BezierPath bezierPath, double errorSquared, boolean connectsCorners) {
    BezierPath.Node lastNode = bezierPath.get(((bezierPath.size()) - 1));
    double error = Math.sqrt(errorSquared);
    if ((connectsCorners && (Geom.lineContainsPoint(lastNode.x[0], lastNode.y[0], bezCurve[3].x, bezCurve[3].y, bezCurve[1].x, bezCurve[1].y, error))) && (Geom.lineContainsPoint(lastNode.x[0], lastNode.y[0], bezCurve[3].x, bezCurve[3].y, bezCurve[2].x, bezCurve[2].y, error))) {
        bezierPath.lineTo(bezCurve[3].x, bezCurve[3].y);
    } else {
        bezierPath.curveTo(bezCurve[1].x, bezCurve[1].y, bezCurve[2].x, bezCurve[2].y, bezCurve[3].x, bezCurve[3].y);
    }
}

/**
 * B0, B1, B2, B3 :
 * 	Bezier multipliers
 */
private static double b0(double u) {
    double tmp = 1.0 - u;
    return (tmp * tmp) * tmp;
}

private static double b1(double u) {
    double tmp = 1.0 - u;
    return (3 * u) * (tmp * tmp);
}

private static double b2(double u) {
    double tmp = 1.0 - u;
    return ((3 * u) * u) * tmp;
}

private static double b3(double u) {
    return (u * u) * u;
}

/**
 * Evaluate a Bezier curve at a particular parameter value.
 *
 * @param degree
 * 		The degree of the bezier curve.
 * @param V
 * 		Array of control points.
 * @param t
 * 		Parametric value to find point for.
 */
private static Point2D.Double bezierII(int degree, Point2D.Double[] V, double t) {
    int i;
    int j;
    Point2D.Double q;/* Point on curve at parameter t */

    Point2D.Double[] vTemp;/* Local copy of control points */

    /* Copy array */
    vTemp = new Point2D.Double[degree + 1];
    for (i = 0; i <= degree; i++) {
        vTemp[i] = ((Point2D.Double) (V[i].clone()));
    }
    /* Triangle computation */
    for (i = 1; i <= degree; i++) {
        for (j = 0; j <= (degree - i); j++) {
            vTemp[j].x = ((1.0 - t) * (vTemp[j].x)) + (t * (vTemp[(j + 1)].x));
            vTemp[j].y = ((1.0 - t) * (vTemp[j].y)) + (t * (vTemp[(j + 1)].y));
        }
    }
    q = vTemp[0];
    return q;
}

/**
 * Assign parameter values to digitized points
 * using relative distances between points.
 *
 * @param d
 * 		Digitized points.
 * @param first
 * 		Indice of first point of region in d.
 * @param last
 * 		Indice of last point of region in d.
 */
private static double[] chordLengthParameterize(ArrayList<Point2D.Double> d, int first, int last) {
    int i;
    double[] u;/* Parameterization */

    u = new double[(last - first) + 1];
    u[0] = 0.0;
    for (i = first + 1; i <= last; i++) {
        u[(i - first)] = (u[((i - first) - 1)]) + (Bezier.v2DistanceBetween2Points(d.get(i), d.get((i - 1))));
    }
    for (i = first + 1; i <= last; i++) {
        u[(i - first)] = (u[(i - first)]) / (u[(last - first)]);
    }
    return u;
}

/**
 * Approximate unit tangents at "center" of digitized curve.
 *
 * @param d
 * 		Digitized points.
 * @param center
 * 		Index to "center" end of region.
 */
private static Point2D.Double computeCenterTangent(ArrayList<Point2D.Double> d, int center) {
    Point2D.Double V1 = new Point2D.Double();
    Point2D.Double V2 = new Point2D.Double();
    Point2D.Double tHatCenter = new Point2D.Double();
    V1 = Bezier.v2SubII(d.get((center - 1)), d.get(center));
    V2 = Bezier.v2SubII(d.get(center), d.get((center + 1)));
    tHatCenter.x = ((V1.x) + (V2.x)) / 2.0;
    tHatCenter.y = ((V1.y) + (V2.y)) / 2.0;
    tHatCenter = Bezier.v2Normalize(tHatCenter);
    return tHatCenter;
}

/**
 * Approximate unit tangents at "left" endpoint of digitized curve.
 *
 * @param d
 * 		Digitized points.
 * @param end
 * 		Index to "left" end of region.
 */
private static Point2D.Double computeLeftTangent(ArrayList<Point2D.Double> d, int end) {
    Point2D.Double tHat1 = new Point2D.Double();
    tHat1 = Bezier.v2SubII(d.get((end + 1)), d.get(end));
    tHat1 = Bezier.v2Normalize(tHat1);
    return tHat1;
}

/**
 * Find the maximum squared distance of digitized points
 * to fitted curve.
 *
 * @param d
 * 		Digitized points.
 * @param first
 * 		Indice of first point of region in d.
 * @param last
 * 		Indice of last point of region in d.
 * @param bezCurve
 * 		Fitted Bezier curve
 * @param u
 * 		Parameterization of points*
 * @param splitPoint
 * 		Point of maximum error (input/output parameter, must be
 * 		an array of 1)
 */
private static double computeMaxError(ArrayList<Point2D.Double> d, int first, int last, Point2D.Double[] bezCurve, double[] u, int[] splitPoint) {
    int i;
    double maxDist;/* Maximum error */

    double dist;/* Current error */

    Point2D.Double P = new Point2D.Double();/* Point on curve */

    Point2D.Double v = new Point2D.Double();/* Vector from point to curve */

    splitPoint[0] = ((last - first) + 1) / 2;
    maxDist = 0.0;
    for (i = first + 1; i < last; i++) {
        P = Bezier.bezierII(3, bezCurve, u[(i - first)]);
        v = Bezier.v2SubII(P, d.get(i));
        dist = Bezier.v2SquaredLength(v);
        if (dist >= maxDist) {
            maxDist = dist;
            splitPoint[0] = i;
        }
    }
    return maxDist;
}

/**
 * Approximate unit tangents at "right" endpoint of digitized curve.
 *
 * @param d
 * 		Digitized points.
 * @param end
 * 		Index to "right" end of region.
 */
private static Point2D.Double computeRightTangent(ArrayList<Point2D.Double> d, int end) {
    Point2D.Double tHat2 = new Point2D.Double();
    tHat2 = Bezier.v2SubII(d.get((end - 1)), d.get(end));
    tHat2 = Bezier.v2Normalize(tHat2);
    return tHat2;
}

/**
 * Finds corners in the provided point list, and returns their indices.
 *
 * @param digitizedPoints
 * 		List of digitized points.
 * @param minAngle
 * 		Minimal angle for corner points
 * @param minDistance
 * 		Minimal distance between a point and adjacent points
 * 		for corner detection
 * @return list of corner indices.
 */
public static ArrayList<Integer> findCorners(List<Point2D.Double> digitizedPoints, double minAngle, double minDistance) {
    ArrayList<Integer> cornerIndices = new ArrayList<Integer>();
    double squaredDistance = minDistance * minDistance;
    int previousCorner = -1;
    double previousCornerAngle = 0;
    for (int i = 1, n = digitizedPoints.size(); i < (n - 1); i++) {
        Point2D.Double p = digitizedPoints.get(i);
        // search for a preceding point for corner detection
        Point2D.Double prev = null;
        boolean intersectsPreviousCorner = false;
        for (int j = i - 1; j >= 0; j--) {
            if ((j == previousCorner) || ((Bezier.v2SquaredDistanceBetween2Points(digitizedPoints.get(j), p)) >= squaredDistance)) {
                prev = digitizedPoints.get(j);
                intersectsPreviousCorner = j < previousCorner;
                break;
            }
        }
        if (prev == null) {
            continue;
        }
        // search for a succeeding point for corner detection
        Point2D.Double next = null;
        for (int j = i + 1; j < n; j++) {
            if ((Bezier.v2SquaredDistanceBetween2Points(digitizedPoints.get(j), p)) >= squaredDistance) {
                next = digitizedPoints.get(j);
                break;
            }
        }
        if (next == null) {
            continue;
        }
        double aPrev = Math.atan2(((prev.y) - (p.y)), ((prev.x) - (p.x)));
        double aNext = Math.atan2(((next.y) - (p.y)), ((next.x) - (p.x)));
        double angle = Math.abs((aPrev - aNext));
        if ((angle < ((Math.PI) - minAngle)) || (angle > ((Math.PI) + minAngle))) {
            if (intersectsPreviousCorner) {
                cornerIndices.set(((cornerIndices.size()) - 1), i);
            } else {
                cornerIndices.add(i);
            }
            previousCorner = i;
            previousCornerAngle = angle;
        }
    }
    return cornerIndices;
}

/**
 * Fits a bezier path to the specified list of digitized points.
 * <p>
 * This is a convenience method for calling fitCubicSegments(List<Point2D.Double>, double);
 *
 * @param digitizedPoints
 * 		digited points.
 * @param error
 * 		the maximal allowed error between the bezier path and the
 * 		digitized points.
 */
public static BezierPath fitBezierPath(Point2D.Double[] digitizedPoints, double error) {
    return Bezier.fitBezierPath(Arrays.asList(digitizedPoints), error);
}

/**
 * Fits a bezier path to the specified list of digitized points.
 *
 * @param digitizedPoints
 * 		digited points.
 * @param error
 * 		the maximal allowed error between the bezier path and the
 * 		digitized points.
 */
public static BezierPath fitBezierPath(List<Point2D.Double> digitizedPoints, double error) {
    // Split into segments at corners
    ArrayList<ArrayList<Point2D.Double>> segments = new ArrayList<ArrayList<Point2D.Double>>();
    segments = Bezier.splitAtCorners(digitizedPoints, ((77 / 180.0) * (Math.PI)), (error * error));
    // Clean up the data in the segments
    for (int i = 0, n = segments.size(); i < n; i++) {
        ArrayList<Point2D.Double> seg = segments.get(i);
        seg = Bezier.removeClosePoints(seg, (error * 2));
        seg = Bezier.reduceNoise(seg, 0.8);
        segments.set(i, seg);
    }
    // Create fitted bezier path
    BezierPath fittedPath = new BezierPath();
    // Quickly deal with empty dataset
    boolean isEmpty = false;
    for (ArrayList<Point2D.Double> seg : segments) {
        if (seg.isEmpty()) {
            isEmpty = false;
            break;
        }
    }
    if (!isEmpty) {
        // Process each segment of digitized points
        double errorSquared = error * error;
        for (ArrayList<Point2D.Double> seg : segments) {
            switch (seg.size()) {
                case 0 :
                    break;
                case 1 :
                    fittedPath.add(new BezierPath.Node(seg.get(0)));
                    break;
                case 2 :
                    if (fittedPath.isEmpty()) {
                        fittedPath.add(new BezierPath.Node(seg.get(0)));
                    }
                    fittedPath.lineTo(seg.get(1).x, seg.get(1).y);
                    break;
                default :
                    if (fittedPath.isEmpty()) {
                        fittedPath.add(new BezierPath.Node(seg.get(0)));
                    }
                    /* Unit tangent vectors at endpoints */
                    Point2D.Double tHat1 = new Point2D.Double();
                    Point2D.Double tHat2 = new Point2D.Double();
                    tHat1 = Bezier.computeLeftTangent(seg, 0);
                    tHat2 = Bezier.computeRightTangent(seg, ((seg.size()) - 1));
                    Bezier.fitCubic(seg, 0, ((seg.size()) - 1), tHat1, tHat2, errorSquared, fittedPath);
                    break;
            }
        }
    }
    return fittedPath;
}

/**
 * Fits a bezier path to the specified list of digitized points.
 * <p>
 * This is a convenience method for calling fitCubicSegments(List<Point2D.Double>, double);
 *
 * @param digitizedPoints
 * 		digited points.
 * @param error
 * 		the maximal allowed error between the bezier path and the
 * 		digitized points.
 */
public static BezierPath fitBezierPath(BezierPath digitizedPoints, double error) {
    ArrayList<Point2D.Double> d = new ArrayList<Point2D.Double>(digitizedPoints.size());
    for (BezierPath.Node n : digitizedPoints) {
        d.add(new Point2D.Double(n.x[0], n.y[0]));
    }
    return Bezier.fitBezierPath(d, error);
}

/**
 * Fit one or multiple subsequent cubic bezier curves to a (sub)set of
 * digitized points. The digitized points represent a smooth curve without
 * corners.
 *
 * @param d
 * 		Array of digitized points. Must not contain subsequent
 * 		coincident points.
 * @param first
 * 		Indice of first point in d.
 * @param last
 * 		Indice of last point in d.
 * @param tHat1
 * 		Unit tangent vectors at start point.
 * @param tHat2
 * 		Unit tanget vector at end point.
 * @param errorSquared
 * 		User-defined errorSquared squared.
 * @param bezierPath
 * 		Path to which the bezier curve segments are added.
 */
private static void fitCubic(ArrayList<Point2D.Double> d, int first, int last, Point2D.Double tHat1, Point2D.Double tHat2, double errorSquared, BezierPath bezierPath) {
    Point2D.Double[] bezCurve;/* Control points of fitted Bezier curve */

    double[] u;/* Parameter values for point */

    double maxError;/* Maximum fitting errorSquared */

    int[] splitPoint = new int[1];/* Point to split point set at.
    This is an array of size one, because we need it as an input/output parameter.
     */

    int nPts;/* Number of points in subset */

    double iterationError;/* Error below which you try iterating */

    int maxIterations = 4;/* Max times to try iterating */

    Point2D.Double tHatCenter = new Point2D.Double();/* Unit tangent vector at splitPoint */

    int i;
    // clone unit tangent vectors, so that we can alter their coordinates
    // without affecting the input values.
    tHat1 = ((Point2D.Double) (tHat1.clone()));
    tHat2 = ((Point2D.Double) (tHat2.clone()));
    iterationError = errorSquared * errorSquared;
    nPts = (last - first) + 1;
    /* Use heuristic if region only has two points in it */
    if (nPts == 2) {
        double dist = (Bezier.v2DistanceBetween2Points(d.get(last), d.get(first))) / 3.0;
        bezCurve = new Point2D.Double[4];
        for (i = 0; i < (bezCurve.length); i++) {
            bezCurve[i] = new Point2D.Double();
        }
        bezCurve[0] = d.get(first);
        bezCurve[3] = d.get(last);
        Bezier.v2Add(bezCurve[0], Bezier.v2Scale(tHat1, dist), bezCurve[1]);
        Bezier.v2Add(bezCurve[3], Bezier.v2Scale(tHat2, dist), bezCurve[2]);
        bezierPath.curveTo(bezCurve[1].x, bezCurve[1].y, bezCurve[2].x, bezCurve[2].y, bezCurve[3].x, bezCurve[3].y);
        return;
    }
    /* Parameterize points, and attempt to fit curve */
    u = Bezier.chordLengthParameterize(d, first, last);
    bezCurve = Bezier.generateBezier(d, first, last, u, tHat1, tHat2);
    /* Find max deviation of points to fitted curve */
    maxError = Bezier.computeMaxError(d, first, last, bezCurve, u, splitPoint);
    if (maxError < errorSquared) {
        Bezier.addCurveTo(bezCurve, bezierPath, errorSquared, ((first == 0) && (last == ((d.size()) - 1))));
        return;
    }
    /* If errorSquared not too large, try some reparameterization */
    /* and iteration */
    if (maxError < iterationError) {
        double[] uPrime;/* Improved parameter values */

        for (i = 0; i < maxIterations; i++) {
            uPrime = Bezier.reparameterize(d, first, last, u, bezCurve);
            bezCurve = Bezier.generateBezier(d, first, last, uPrime, tHat1, tHat2);
            maxError = Bezier.computeMaxError(d, first, last, bezCurve, uPrime, splitPoint);
            if (maxError < errorSquared) {
                Bezier.addCurveTo(bezCurve, bezierPath, errorSquared, ((first == 0) && (last == ((d.size()) - 1))));
                return;
            }
            u = uPrime;
        }
    }
    /* Fitting failed -- split at max errorSquared point and fit recursively */
    tHatCenter = Bezier.computeCenterTangent(d, splitPoint[0]);
    if (first < (splitPoint[0])) {
        Bezier.fitCubic(d, first, splitPoint[0], tHat1, tHatCenter, errorSquared, bezierPath);
    } else {
        bezierPath.lineTo(d.get(splitPoint[0]).x, d.get(splitPoint[0]).y);
        // System.err.println("Cant split any further " + first + ".." + splitPoint[0]);
    }
    Bezier.v2Negate(tHatCenter);
    if ((splitPoint[0]) < last) {
        Bezier.fitCubic(d, splitPoint[0], last, tHatCenter, tHat2, errorSquared, bezierPath);
    } else {
        bezierPath.lineTo(d.get(last).x, d.get(last).y);
        // System.err.println("Cant split any further " + splitPoint[0] + ".." + last);
    }
}

/**
 * Use least-squares method to find Bezier control points for region.
 *
 * @param d
 * 		Array of digitized points.
 * @param first
 * 		Indice of first point in d.
 * @param last
 * 		Indice of last point in d.
 * @param uPrime
 * 		Parameter values for region .
 * @param tHat1
 * 		Unit tangent vectors at start point.
 * @param tHat2
 * 		Unit tanget vector at end point.
 * @return A cubic bezier curve consisting of 4 control points.
 */
private static Point2D.Double[] generateBezier(ArrayList<Point2D.Double> d, int first, int last, double[] uPrime, Point2D.Double tHat1, Point2D.Double tHat2) {
    Point2D.Double[] bezCurve;
    bezCurve = new Point2D.Double[4];
    for (int i = 0; i < (bezCurve.length); i++) {
        bezCurve[i] = new Point2D.Double();
    }
    /* Use the Wu/Barsky heuristic */
    double dist = (Bezier.v2DistanceBetween2Points(d.get(last), d.get(first))) / 3.0;
    bezCurve[0] = d.get(first);
    bezCurve[3] = d.get(last);
    Bezier.v2Add(bezCurve[0], Bezier.v2Scale(tHat1, dist), bezCurve[1]);
    Bezier.v2Add(bezCurve[3], Bezier.v2Scale(tHat2, dist), bezCurve[2]);
    return bezCurve;
}

