                break;
            case PathIterator.SEG_CUBICTO :
                bp.curveTo(coords[0], coords[1], coords[2], coords[3], coords[4], coords[5]);
                break;
            case PathIterator.SEG_CLOSE :
                bp.setClosed(true);
