    if (obj instanceof JMixer.Preset) {
        JMixer.Preset preset = ((JMixer.Preset) (obj));
        HarmonicColorModel m = harmonicWheel.getHarmonicColorModel();
        m.set(m.getBase(), preset.getCompositeColor());
    }
}// GEN-LAST:event_presetPerformed

