        ColorSliderModel m = ((ColorSliderModel) (e.getSource()));
        color = m.getColor();
        previewLabel.setBackground(color);
        for (ColorSliderModel c : models) {
            if (c != m) {
                c.setColor(color);
            }
        }
    }
    (adjusting)--;
}

