        double width = strokeTotalWidth / 2.0;
        if ((AttributeKeys.STROKE_JOIN.get(this)) == (BasicStroke.JOIN_MITER)) {
            width *= AttributeKeys.STROKE_MITER_LIMIT.get(this);
        } else
