/**
 * Converts an ODG draw:transform attribute value into an AffineTransform.
 * <p>
 * The draw:transform attribute specifies a list of transformations that can be applied to a
 * drawing shape.
 * The value of this attribute is a list of transform definitions, which are applied to the drawing shape
 * in the order in which they are listed. The transform definitions in the list must be separated by a
 * white space and/or a comma. The types of transform definitions available include:
 * • matrix(<a> <b> <c> <d> <e> <f>), which specifies a transformation in the form of a
 * transformation matrix of six values. matrix(a,b,c,d,e,f) is the equivalent of applying the
 * transformation matrix [a b c d e f].
 * • translate(<tx> [<ty>]), which specifies a translation by tx and ty.
 * • scale(<sx> [<sy>]), which specifies a scale operation by sx and sy. If <sy> is not
 * provided, it is assumed to be equal to <sx>.
 * • rotate(<rotate-angle>), which specifies a rotation by <rotate-angle> about the
 * origin of the shapes coordinate system.
 * • skewX(<skew-angle>), which specifies a skew transformation along the X axis.
 * • skewY(<skew-angle>), which specifies a skew transformation along the Y axis.
 */
public static AffineTransform toTransform(String str) throws IOException {
    AffineTransform t = new AffineTransform();
    AffineTransform t2 = new AffineTransform();
    if (str != null) {
        StreamPosTokenizer tt = new StreamPosTokenizer(new StringReader(str));
        tt.resetSyntax();
        tt.wordChars(a, z);
        tt.wordChars(A, Z);
        tt.wordChars((128 + 32), 255);
        tt.whitespaceChars(0,  );
        tt.whitespaceChars(,, ,);
        tt.parseNumbers();
        tt.parseExponents();
        while ((tt.nextToken()) != (StreamPosTokenizer.TT_EOF)) {
            if ((tt.ttype) != (StreamPosTokenizer.TT_WORD)) {
                throw new IOException(("Illegal transform " + str));
            }
            String type = tt.sval;
            if ((tt.nextToken()) != () {
                throw new IOException(("( not found in transform " + str));
            }
            if (type.equals("matrix")) {
                double[] m = new double[6];
                for (int i = 0; i < 6; i++) {
                    if ((tt.nextToken()) != (StreamPosTokenizer.TT_NUMBER)) {
                        throw new IOException(((((((("Matrix value " + i) + " not found in transform ") + str) + " token:") + (tt.ttype)) + " ") + (tt.sval)));
                    }
                    m[i] = tt.nval;
                }
                t.preConcatenate(new AffineTransform(m));
            } else
                if (type.equals("translate")) {
                    double tx;
                    double ty;
                    if ((tt.nextToken()) != (StreamPosTokenizer.TT_NUMBER)) {
                        throw new IOException(("X-translation value not found in transform " + str));
                    }
                    tx = tt.nval;
                    if ((tt.nextToken()) == (StreamPosTokenizer.TT_WORD)) {
                        tx *= ODGInputFormat.toUnitFactor(tt.sval);
                    } else {
                        tt.pushBack();
                    }
                    if ((tt.nextToken()) == (StreamPosTokenizer.TT_NUMBER)) {
                        ty = tt.nval;
                        if ((tt.nextToken()) == (StreamPosTokenizer.TT_WORD)) {
                            ty *= ODGInputFormat.toUnitFactor(tt.sval);
                        } else {
                            tt.pushBack();
                        }
                    } else {
                        tt.pushBack();
                        ty = 0;
                    }
                    t2.setToIdentity();
                    t2.translate(tx, ty);
                    t.preConcatenate(t2);
                } else
                    if (type.equals("scale")) {
                        double sx;
                        double sy;
                        if ((tt.nextToken()) != (StreamPosTokenizer.TT_NUMBER)) {
                            throw new IOException(("X-scale value not found in transform " + str));
                        }
                        sx = tt.nval;
                        if ((tt.nextToken()) == (StreamPosTokenizer.TT_NUMBER)) {
                            sy = tt.nval;
                        } else {
                            tt.pushBack();
                            sy = sx;
                        }
                        t2.setToIdentity();
                        t2.scale(sx, sy);
                        t.preConcatenate(t2);
                    } else
                        if (type.equals("rotate")) {
                            double angle;
                            double cx;
                            double cy;
                            if ((tt.nextToken()) != (StreamPosTokenizer.TT_NUMBER)) {
                                throw new IOException(("Angle value not found in transform " + str));
                            }
                            angle = tt.nval;
                            t2.setToIdentity();
                            t2.rotate((-angle));
                            t.preConcatenate(t2);
                        } else
                            if (type.equals("skewX")) {
                                double angle;
                                if ((tt.nextToken()) != (StreamPosTokenizer.TT_NUMBER)) {
                                    throw new IOException(("Skew angle not found in transform " + str));
                                }
                                angle = tt.nval;
                                t.preConcatenate(new AffineTransform(1, 0, Math.tan(((angle * (Math.PI)) / 180)), 1, 0, 0));
                            } else
                                if (type.equals("skewY")) {
                                    double angle;
                                    if ((tt.nextToken()) != (StreamPosTokenizer.TT_NUMBER)) {
                                        throw new IOException(("Skew angle not found in transform " + str));
                                    }
                                    angle = tt.nval;
                                    t.preConcatenate(new AffineTransform(1, Math.tan(((angle * (Math.PI)) / 180)), 0, 1, 0, 0));
                                } else {
                                    throw new IOException(((("Unknown transform " + type) + " in ") + str));
                                }





            if ((tt.nextToken()) != )) {
                throw new IOException((") not found in transform " + str));
            }
        } 
    }
    return t;
}

private static double toUnitFactor(String str) throws IOException {
    double scaleFactor;
    if (str.equals("px")) {
        scaleFactor = 1.0;
    } else
        if (str.endsWith("pt")) {
            scaleFactor = 1.25;
        } else
            if (str.endsWith("pc")) {
                scaleFactor = 15;
            } else
                if (str.endsWith("mm")) {
                    scaleFactor = 3.543307;
                } else
                    if (str.endsWith("cm")) {
                        scaleFactor = 35.43307;
                    } else
                        if (str.endsWith("in")) {
                            scaleFactor = 90;
                        } else {
                            scaleFactor = 1.0;
                        }





    return scaleFactor;
}

/**
 * Returns a value as a String array.
 * The values are separated by whitespace or by commas with optional white
 * space.
 */
public static String[] toWSOrCommaSeparatedArray(String str) throws IOException {
    String[] result = str.split("(\s*,\s*|\s+)");
    if (((result.length) == 1) && (result[0].equals(""))) {
        return new String[0];
    } else {
        return result;
    }
}

public Map<AttributeKey, Object> getAttributes(String styleName, String familyName) {
    // String key = familyName+"-"+styleName;
    String key = styleName;
    ODGStylesReader.Style style;
    if (commonStyles.containsKey(key)) {
        style = commonStyles.get(key);
    } else
        if (automaticStyles.containsKey(key)) {
            style = automaticStyles.get(key);
        } else
            if (masterStyles.containsKey(key)) {
                style = masterStyles.get(key);
            } else {
                style = new ODGStylesReader.Style();
            }


    if ((style.parentName) == null) {
        return style;
    } else {
        HashMap<AttributeKey, Object> a = new HashMap<AttributeKey, Object>();
        Map<AttributeKey, Object> parentAttributes = getAttributes(style.parentName, familyName);
        a.putAll(parentAttributes);
        a.putAll(style);
        return a;
    }
}

/**
 * Reads a &lt;document-styles&gt; element from the specified
 * XML file.
 *
 * @param file
 * 		A XML file with a &lt;document&gt; root element
 * 		or with a &lt;document-styles&gt; root element.
 */
public void read(File file) throws IOException {
    BufferedInputStream in = null;
    try {
        in = new BufferedInputStream(new FileInputStream(file));
        read(in);
    } finally {
        if (in != null) {
            in.close();
        }
    }
}

/**
 * Reads a &lt;document-styles&gt; element from the specified
 * input stream.
 *
 * @param in
 * 		A input stream with a &lt;document&gt; root element
 * 		or with a &lt;document-styles&gt; root element.
 */
public void read(InputStream in) throws IOException {
    IXMLParser parser;
    try {
        parser = XMLParserFactory.createDefaultXMLParser();
    } catch (Exception ex) {
        InternalError e = new InternalError("Unable to instantiate NanoXML Parser");
        e.initCause(ex);
        throw e;
    }
    IXMLReader reader = new StdXMLReader(in);
    parser.setReader(reader);
    IXMLElement document;
    try {
        document = ((IXMLElement) (parser.parse()));
    } catch (XMLException ex) {
        IOException e = new IOException(ex.getMessage());
        e.initCause(ex);
        throw e;
    }
    read(document);
}

/**
 * Reads a &lt;document-styles&gt; element from the specified
 * XML element.
 *
 * @param root
 * 		A &lt;document&gt; element or a
 * 		&lt;document-styles&gt; element.
 */
public void read(IXMLElement root) throws IOException {
    String name = root.getName();
    String ns = root.getNamespace();
    if ((name.equals("document-content")) && ((ns == null) || (ns.equals(ODGConstants.OFFICE_NAMESPACE)))) {
        readDocumentContentElement(root);
    } else
        if ((name.equals("document-styles")) && ((ns == null) || (ns.equals(ODGConstants.OFFICE_NAMESPACE)))) {
            readDocumentStylesElement(root);
        } else {
            if (ODGStylesReader.DEBUG)
                System.out.println(("ODGStylesReader unsupported root element " + root));

        }

}

