                            } else {
                                if (nextCommand != Q) {
                                    buf.append(" Q ");
                                    nextCommand = Q;
                                } else {
                                    buf.append( );
                                }
                                buf.append(SVGOutputFormat.toNumber(current.x[1]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.y[1]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.x[0]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.y[0]));
                            }
                        } else {
                            if (((current.mask) & (BezierPath.C1_MASK)) == 0) {
                                if (nextCommand != Q) {
                                    buf.append(" Q ");
                                    nextCommand = Q;
                                } else {
                                    buf.append( );
                                }
                                buf.append(SVGOutputFormat.toNumber(previous.x[2]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(previous.y[2]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.x[0]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.y[0]));
                            } else {
                                if (nextCommand != C) {
                                    buf.append(" C ");
                                    nextCommand = C;
                                } else {
                                    buf.append( );
                                }
                                buf.append(SVGOutputFormat.toNumber(previous.x[2]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(previous.y[2]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.x[1]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.y[1]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.x[0]));
                                buf.append( );
                                buf.append(SVGOutputFormat.toNumber(current.y[0]));
                            }
                        }
                    }
                    buf.append(" Z");
                    nextCommand = u0000;
                }
            }

    }
    return buf.toString();
}

/**
