private void updateMatcher() {
    TeddyView view = ((TeddyView) (app.getActiveView()));
    if (view != null) {
        MatchType matchType;
        switch (modeCombo.getSelectedIndex()) {
            case 0 :
                matchType = MatchType.CONTAINS;
