@Override
public Object stringToValue(String str) throws ParseException {
    // Handle null and empty case
    if ((str == null) || ((str.trim().length()) == 0)) {
        if (allowsNullValue) {
            return null;
        } else {
            throw new ParseException("Null value is not allowed.", 0);
        }
    }
    // Format RGB_HEX
    Matcher matcher = ColorFormatter.rgbHexPattern.matcher(str);
    if (matcher.matches()) {
        setLastUsedInputFormat(ColorFormatter.Format.RGB_HEX);
        try {
            String group1 = matcher.group(1);
            if ((group1.length()) == 3) {
                return new Color(// 
                Integer.parseInt((((((("" + (group1.charAt(0))) + (group1.charAt(0)))// 
                 + (group1.charAt(1))) + (group1.charAt(1)))// 
                 + (group1.charAt(2))) + (group1.charAt(2))), 16));
            } else
                if ((group1.length()) == 6) {
                    return new Color(Integer.parseInt(group1, 16));
                } else {
                    throw new ParseException("Hex color must have 3 or 6 digits.", 1);
                }

        } catch (NumberFormatException nfe) {
            ParseException pe = new ParseException(str, 0);
            pe.initCause(nfe);
            throw pe;
        }
    }
    // Format RGB_INTEGER
    matcher = ColorFormatter.rgbIntegerPattern.matcher(str);
    if (matcher.matches()) {
        setLastUsedInputFormat(ColorFormatter.Format.RGB_INTEGER);
        try {
            return // 
            // 
            // 
            new Color(Integer.parseInt(matcher.group(1)), Integer.parseInt(matcher.group(2)), Integer.parseInt(matcher.group(3)));
        } catch (NumberFormatException nfe) {
            ParseException pe = new ParseException(str, 0);
            pe.initCause(nfe);
            throw pe;
        } catch (IllegalArgumentException iae) {
            ParseException pe = new ParseException(str, 0);
            pe.initCause(iae);
            throw pe;
        }
    }
    throw new ParseException(str, 0);
}

@Override
public String valueToString(Object value) throws ParseException {
    String str = null;
    if (value == null) {
        if (allowsNullValue) {
            str = "";
        } else {
            throw new ParseException("Null value is not allowed.", 0);
        }
    } else {
        if (!(value instanceof Color)) {
            throw new ParseException(("Value is not a color " + value), 0);
        }
        Color c = ((Color) (value));
        switch (outputFormat) {
            case RGB_HEX :
                str = "000000" + (Integer.toHexString(((c.getRGB()) & 16777215)));
                str = "#" + (str.substring(((str.length()) - 6)));
                break;
            case RGB_INTEGER :
                str = ((((c.getRed()) + ",") + (c.getGreen())) + ",") + (c.getBlue());
                break;
        }
    }
    return str;
}

