public void writeObject(Object o) throws IOException {
    if (o == null) {
        openElement("null");
        closeElement();
    } else
        if (o instanceof DOMStorable) {
            writeStorable(((DOMStorable) (o)));
        } else
            if (o instanceof String) {
                openElement("string");
                addText(((String) (o)));
                closeElement();
            } else
                if (o instanceof Integer) {
                    openElement("int");
                    addText(o.toString());
                    closeElement();
                } else
                    if (o instanceof Long) {
                        openElement("long");
                        addText(o.toString());
                        closeElement();
                    } else
                        if (o instanceof Double) {
                            openElement("double");
                            // Remove the awkard .0 at the end of each number
                            String str = o.toString();
                            if (str.endsWith(".0"))
                                str = str.substring(0, ((str.length()) - 2));

                            addText(str);
                            closeElement();
                        } else
                            if (o instanceof Float) {
                                openElement("float");
                                // Remove the awkard .0 at the end of each number
                                String str = o.toString();
                                if (str.endsWith(".0"))
                                    str = str.substring(0, ((str.length()) - 2));

                                addText(str);
                                closeElement();
                            } else
                                if (o instanceof Boolean) {
                                    openElement("boolean");
                                    addText(o.toString());
                                    closeElement();
                                } else
                                    if (o instanceof Color) {
                                        Color c = ((Color) (o));
                                        openElement("color");
                                        addAttribute("rgba", ("#" + (Integer.toHexString(c.getRGB()))));
                                        closeElement();
                                    } else
                                        if (o instanceof int[]) {
                                            openElement("intArray");
                                            int[] a = ((int[]) (o));
                                            for (int i = 0; i < (a.length); i++) {
                                                writeObject(new Integer(a[i]));
                                            }
                                            closeElement();
                                        } else
                                            if (o instanceof float[]) {
                                                openElement("floatArray");
                                                float[] a = ((float[]) (o));
                                                for (int i = 0; i < (a.length); i++) {
                                                    writeObject(new Float(a[i]));
                                                }
                                                closeElement();
                                            } else
                                                if (o instanceof double[]) {
                                                    openElement("doubleArray");
                                                    double[] a = ((double[]) (o));
                                                    for (int i = 0; i < (a.length); i++) {
                                                        writeObject(new Double(a[i]));
                                                    }
                                                    closeElement();
                                                } else
                                                    if (o instanceof Font) {
                                                        Font f = ((Font) (o));
                                                        openElement("font");
                                                        addAttribute("name", f.getName());
                                                        addAttribute("style", f.getStyle());
                                                        addAttribute("size", f.getSize());
                                                        closeElement();
                                                    } else
                                                        if (o instanceof Enum) {
                                                            openElement("enum");
                                                            Enum e = ((Enum) (o));
                                                            addAttribute("type", factory.getEnumName(e));
                                                            addText(factory.getEnumValue(e));
                                                            closeElement();
                                                        } else {
                                                            throw new IllegalArgumentException(((("unable to store: " + o) + " ") + (o.getClass())));
                                                        }













}

private XMLElement writeStorable(DOMStorable o) throws IOException {
    String tagName = factory.getName(o);
    if (tagName == null)
        throw new IllegalArgumentException(("no tag name for:" + o));

    openElement(tagName);
    XMLElement element = current;
    if (objectids.containsKey(o)) {
        addAttribute("ref", ((String) (objectids.get(o))));
    } else {
        String id = Integer.toString(objectids.size(), 16);
        objectids.put(o, id);
        addAttribute("id", id);
        o.write(this);
    }
    closeElement();
    return element;
}

public Object create(String name) {
    name = unescape(name);
    try {
        return Class.forName(name).newInstance();
    } catch (InstantiationException ex) {
        IllegalArgumentException e = new IllegalArgumentException((("Class " + name) + " can not instantiate an object"));
        e.initCause(ex);
        throw e;
    } catch (IllegalAccessException ex) {
        IllegalArgumentException e = new IllegalArgumentException((("Class " + name) + " is not public"));
        e.initCause(ex);
        throw e;
    } catch (ClassNotFoundException ex) {
        IllegalArgumentException e = new IllegalArgumentException((("Class " + name) + " does not exist"));
        e.initCause(ex);
        throw e;
    }
}

@SuppressWarnings("unchecked")
public Enum createEnum(String name, String value) {
    name = unescape(name);
    Class enumClass;
    try {
        enumClass = Class.forName(name);
    } catch (ClassNotFoundException ex) {
        throw new IllegalArgumentException(("Enum name not known to factory:" + name));
    }
    if (enumClass == null) {
        throw new IllegalArgumentException(("Enum name not known to factory:" + name));
    }
    return Enum.valueOf(enumClass, value);
    // throw new IllegalArgumentException("Enum value not known to factory:"+value);
}

private String escape(String name) {
    // Escape dollar characters by two full-stop characters
    name = name.replaceAll("\$", "..");
    return name;
}

public String getEnumName(Enum o) {
    return escape(o.getClass().getName());
}

public String getEnumValue(Enum o) {
    return o.name();
}

public String getName(DOMStorable o) {
    return escape(o.getClass().getName());
}

private String unescape(String name) {
    // Unescape dollar characters from two full-stop characters
    name = name.replaceAll("\.\.", Matcher.quoteReplacement("$"));
    return name;
}

/**
 * Creates new XMLTransferable
 */
public XMLTransferable(byte[] data, String mimeType, String humanPresentableName) {
    this.data = data;
    this.flavor = new DataFlavor(mimeType, humanPresentableName);
}

/**
 * Returns an object which represents the data to be transferred.  The class
 * of the object returned is defined by the representation class of the flavor.
 *
 * @param flavor
 * 		the requested flavor for the data
 * @see DataFlavor#getRepresentationClass
 * @exception IOException                if the data is no longer available
in the requested flavor.
 * @exception UnsupportedFlavorException if the requested data flavor is
not supported.
 */
public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException, IOException {
    if (this.flavor.equals(flavor)) {
        return new ByteArrayInputStream(data);
    } else {
        throw new UnsupportedFlavorException(flavor);
    }
}

/**
 * Returns an array of DataFlavor objects indicating the flavors the data
 * can be provided in.  The array should be ordered according to preference
 * for providing the data (from most richly descriptive to least descriptive).
 *
 * @return an array of data flavors in which this data can be transferred
 */
public DataFlavor[] getTransferDataFlavors() {
    return new DataFlavor[]{ flavor };
}

/**
 * Returns whether or not the specified data flavor is supported for
 * this object.
 *
 * @param flavor
 * 		the requested flavor for the data
 * @return boolean indicating wjether or not the data flavor is supported
 */
public boolean isDataFlavorSupported(DataFlavor flavor) {
    return this.flavor.equals(flavor);
}

public void parse(Reader css, StyleManager rm) throws IOException {
    StreamTokenizer tt = new StreamTokenizer(css);
    tt.resetSyntax();
    tt.wordChars(a, z);
    tt.wordChars(A, Z);
    tt.wordChars(0, 9);
    tt.wordChars((128 + 32), 255);
    tt.whitespaceChars(0,  );
    tt.commentChar(/);
    tt.slashStarComments(true);
    parseStylesheet(tt, rm);
}

public void parse(String css, StyleManager rm) throws IOException {
    parse(new StringReader(css), rm);
}

private Map<String, String> parseDeclarationMap(StreamTokenizer tt) throws IOException {
    HashMap<String, String> map = new HashMap<String, String>();
    do {
        // Parse key
        StringBuilder key = new StringBuilder();
        while (((((tt.nextToken()) != (StreamTokenizer.TT_EOF)) && ((tt.ttype) != })) && ((tt.ttype) != :)) && ((tt.ttype) != ;)) {
            switch (tt.ttype) {
                case StreamTokenizer.TT_WORD :
                    key.append(tt.sval);
                    break;
                default :
                    key.append(((char) (tt.ttype)));
                    break;
            }
        } 
        if (((tt.ttype) == }) && ((key.length()) == 0)) {
            break;
        }
        if ((tt.ttype) != :)
            throw new IOException(("Declaration : missing for " + key));

        // Parse value
        StringBuilder value = new StringBuilder();
        boolean needsWhitespace = false;
        while ((((tt.nextToken()) != (StreamTokenizer.TT_EOF)) && ((tt.ttype) != ;)) && ((tt.ttype) != })) {
            switch (tt.ttype) {
                case StreamTokenizer.TT_WORD :
                    if (needsWhitespace)
                        value.append( );

                    value.append(tt.sval);
                    needsWhitespace = true;
                    break;
                default :
                    value.append(((char) (tt.ttype)));
                    needsWhitespace = false;
                    break;
            }
        } 
        map.put(key.toString(), value.toString());
        // System.out.println("  declaration: "+key+":"+value);
    } while (((tt.ttype) != }) && ((tt.ttype) != (StreamTokenizer.TT_EOF)) );
    tt.pushBack();
    return map;
}

private void parseRuleset(StreamTokenizer tt, StyleManager rm) throws IOException {
    // parse selector list
    List<String> selectors = parseSelectorList(tt);
    if ((tt.nextToken()) != {)
        throw new IOException(("Ruleset { missing for " + selectors));

    Map<String, String> declarations = parseDeclarationMap(tt);
    if ((tt.nextToken()) != })
        throw new IOException(("Ruleset } missing for " + selectors));

    for (String selector : selectors) {
        rm.add(new CSSRule(selector, declarations));
        // System.out.println("CSSParser.add("+selector+","+declarations);
        /* for (Map.Entry<String,String> entry : declarations.entrySet()) {
        rm.add(new CSSRule(selector, entry.getKey(), entry.getValue()));
        }
         */
    }
}

private List<String> parseSelectorList(StreamTokenizer tt) throws IOException {
    LinkedList<String> list = new LinkedList<String>();
    StringBuilder selector = new StringBuilder();
    boolean needsWhitespace = false;
    while (((tt.nextToken()) != (StreamTokenizer.TT_EOF)) && ((tt.ttype) != {)) {
        switch (tt.ttype) {
            case StreamTokenizer.TT_WORD :
                if (needsWhitespace)
                    selector.append( );

                selector.append(tt.sval);
                needsWhitespace = true;
                break;
            case , :
                list.add(selector.toString());
                selector.setLength(0);
                needsWhitespace = false;
                break;
            default :
                if (needsWhitespace)
                    selector.append( );

                selector.append(((char) (tt.ttype)));
                needsWhitespace = false;
                break;
        }
    } 
    if ((selector.length()) != 0) {
        list.add(selector.toString());
    }
    tt.pushBack();
    // System.out.println("selectors:"+list);
    return list;
}

private void parseStylesheet(StreamTokenizer tt, StyleManager rm) throws IOException {
    while ((tt.nextToken()) != (StreamTokenizer.TT_EOF)) {
        tt.pushBack();
        parseRuleset(tt, rm);
    } 
}

public CSSRule(String name, String value) {
