    properties.put(name, value);
}

public CSSRule(String selector, String propertyName, String propertyValue) {
    setSelector(selector);
    properties = new HashMap<String, String>();
    properties.put(propertyName, propertyValue);
}

public CSSRule(String selector, Map<String, String> properties) {
    setSelector(selector);
    this.properties = properties;
}

public void apply(IXMLElement elem) {
    for (Map.Entry<String, String> property : properties.entrySet()) {
        if (!(elem.hasAttribute(property.getKey()))) {
            elem.setAttribute(property.getKey(), property.getValue());
        }
    }
}

public void apply(Element elem) {
    for (Map.Entry<String, String> property : properties.entrySet()) {
        if (!(elem.hasAttribute(property.getKey()))) {
            elem.setAttribute(property.getKey(), property.getValue());
        }
    }
}

public boolean matches(IXMLElement elem) {
    boolean isMatch = false;
    switch (type) {
        case ALL :
            isMatch = true;
            break;
        case ELEMENT_NAME :
            {
                String name = elem.getName();
                isMatch = (name != null) && (name.equals(selector));
                break;
            }
        case CLASS_ATTRIBUTE :
            {
                String value = elem.getAttribute("class");
                if (value != null) {
                    String[] clazzes = value.split(" ");
                    for (String clazz : clazzes) {
                        if (clazz.equals(selector)) {
                            isMatch = true;
                            break;
                        }
                    }
                }
                break;
            }
        case ID_ATTRIBUTE :
            {
                String name = elem.getAttribute("id");
                isMatch = (name != null) && (name.equals(selector));
                break;
            }
    }
    return isMatch;
}

public boolean matches(Element elem) {
    boolean isMatch = false;
    switch (type) {
        case ALL :
            isMatch = true;
            break;
        case ELEMENT_NAME :
            {
                String name = elem.getLocalName();
                isMatch = name.equals(selector);
                break;
            }
        case CLASS_ATTRIBUTE :
            {
                String value = elem.getAttribute("class");
                if (value != null) {
                    String[] clazzes = value.split(" ");
                    for (String clazz : clazzes) {
                        if (clazz.equals(selector)) {
                            isMatch = true;
                            break;
                        }
                    }
                }
                break;
            }
        case ID_ATTRIBUTE :
            {
                String name = elem.getAttribute("id");
                isMatch = (name != null) && (name.equals(selector));
                break;
            }
    }
    return isMatch;
}

public void setSelector(String selector) {
    switch (selector.charAt(0)) {
        case * :
            type = CSSRule.SelectorType.ALL;
            break;
        case . :
            type = CSSRule.SelectorType.CLASS_ATTRIBUTE;
            break;
        case # :
            type = CSSRule.SelectorType.ID_ATTRIBUTE;
            break;
        default :
            type = CSSRule.SelectorType.ELEMENT_NAME;
            break;
    }
    this.selector = ((type) == (CSSRule.SelectorType.ELEMENT_NAME)) ? selector : selector.substring(1);
}

public String toString() {
    return (("CSSRule[" + (selector)) + (properties)) + "]";
}

public StyleManager() {
    rules = new ArrayList<CSSRule>();
}

public void add(CSSRule rule) {
    rules.add(rule);
}

public void applyStylesTo(IXMLElement elem) {
    for (CSSRule rule : new ReversedList<CSSRule>(rules)) {
        if (rule.matches(elem)) {
            // System.out.println("StyleManager applying "+rule+" to "+elem);
            rule.apply(elem);
        }
    }
}

public void applyStylesTo(Element elem) {
    for (CSSRule rule : rules) {
        if (rule.matches(elem)) {
            rule.apply(elem);
        }
    }
}
